52		}
53		if m != nil {
54			t.Fatalf("map = %v, want nil", m)
55		}
56		after, err := os.ReadFile(path)
57		if err != nil {
58			t.Fatal(err)
59		}
60		if string(before) != string(after) {
61			t.Fatal("file modified by rejected Open")
62		}
63	}
64	
65	// 校正记录必须恰好覆盖声明范围内的每一帧：缺失、重复、错序、范围外的
66	// 额外条目、前后时间不一致，或锚点/结束时间不命中已导入帧，都按损坏
67	// 拒绝。
68	func TestOpenRejectsIncompleteCorrectionRecords(t *testing.T) {
69		cases := []struct {
70			name string
71			fn   func(fd *fileData)
72		}{
73			{"missing middle frame", func(fd *fileData) {
74				p := fd.Corrections[0].Poses
75				fd.Corrections[0].Poses = []poseChangeJSON{p[0], p[2]}
76			}},
77			{"missing last frame", func(fd *fileData) {
78				fd.Corrections[0].Poses = fd.Corrections[0].Poses[:2]
79			}},
80			{"duplicate frame replaces another", func(fd *fileData) {
81				fd.Corrections[0].Poses[1] = fd.Corrections[0].Poses[0]
82			}},
83			{"out of order", func(fd *fileData) {
84				p := fd.Corrections[0].Poses
85				p[0], p[1] = p[1], p[0]
86			}},
87			{"extra frame beyond range", func(fd *fileData) {
88				p := fd.Corrections[0].Poses
89				extra := p[2]
90				extra.Before.Time, extra.After.Time = 400, 400
91				fd.Corrections[0].Poses = append(p, extra)
92			}},
93			{"before and after times differ", func(fd *fileData) {
94				fd.Corrections[0].Poses[1].After.Time = 250
95			}},
96			{"pose time not on any frame", func(fd *fileData) {
97				fd.Corrections[0].Poses[1].Before.Time = 250
98				fd.Corrections[0].Poses[1].After.Time = 250
99			}},
100			{"anchor is initial pose", func(fd *fileData) {
101				fd.Corrections[0].Anchor = 0
102			}},
103			{"end time is initial pose", func(fd *fileData) {
104				fd.Corrections[0].Anchor = 0
105				fd.Corrections[0].EndTime = 0
106				fd.Corrections[0].Poses = fd.Corrections[0].Poses[:1]
107			}},
108			{"anchor between frames", func(fd *fileData) {
109				fd.Corrections[0].Anchor = 150
110			}},
111			{"end time between frames", func(fd *fileData) {
112				fd.Corrections[0].EndTime = 250
113			}},
114			{"anchor shifted to later frame", func(fd *fileData) {
115				fd.Corrections[0].Anchor = 200
116			}},
117			{"anchor after end time", func(fd *fileData) {
118				fd.Corrections[0].Anchor = 300
119				fd.Corrections[0].EndTime = 100
120			}},
121		}
122		for _, tc := range cases {
123			t.Run(tc.name, func(t *testing.T) {
124				path := filepath.Join(t.TempDir(), "m.pose")
125				buildCorrectedMap(t, path)
126				tamperFile(t, path, tc.fn)
127				assertOpenCorrupt(t, path)
128			})
129		}
130	}
131	
132	// 未篡改的校正记录正常打开，记录按原提交次序返回且内容保持保存时的
133	// 快照。
134	func TestOpenAcceptsCompleteCorrectionRecord(t *testing.T) {
