165			t.Fatal(err)
166		}
167		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
168			{Time: 100, DX: 1},
169			{Time: 200, DX: 1},
170		}}); err != nil {
171			t.Fatal(err)
172		}
173		if _, err := m.Correct(Correction{ID: "c1", Anchor: 200, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
174			t.Fatal(err)
175		}
