177			t.Fatal(err)
178		}
179	
180		m2, err := Open(path)
181		if err != nil {
182			t.Fatalf("open: %v", err)
183		}
184		defer m2.Close()
185		recs, _ := m2.Corrections()
186		if len(recs) != 1 || recs[0].Anchor != 200 || recs[0].EndTime != 200 || len(recs[0].Poses) != 1 {
187			t.Fatalf("records = %+v", recs)
188		}
189	}
190	
191	// 对相同范围再次校正、且之后导入新帧：较早记录仍只覆盖提交时的范围并
192	// 保留当时的前后值，新帧不属于之前的记录；两条记录都合法，重开后按
193	// 提交次序返回。
194	func TestOpenAcceptsRecorrectionAndLaterFrames(t *testing.T) {
195		path := filepath.Join(t.TempDir(), "m.pose")
196		m, err := Create(path, baseConfig())
197		if err != nil {
198			t.Fatal(err)
