200		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
201			{Time: 100, DX: 1},
202			{Time: 200, DX: 1},
203			{Time: 300, DX: 1},
204		}}); err != nil {
205			t.Fatal(err)
206		}
207		rec1, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}})
208		if err != nil {
209			t.Fatal(err)
210		}
211		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{{Time: 400, DX: 1}}}); err != nil {
212			t.Fatal(err)
213		}
214		rec2, err := m.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: 7, Y: 8, Variance: 2}})
215		if err != nil {
