217	
218	// 同一标识失效后再现：校正范围跨越两次出现时，两次出现必须分别对应；
219	// 失效时刻（t=200）的观测属于旧出现，下一次出现的首次观测（t=300）属于
220	// 新出现。已失效的旧出现不能因当前区域查询不返回它而被排除。
221	func TestOpenCorrectionAcrossOccurrences(t *testing.T) {
222		path := filepath.Join(t.TempDir(), "m.pose")
223		buildOccurrenceMap(t, path) // t=100 L/1、t=200 L/1（当时失效）、t=300 L/2
224		m, err := Open(path)
225		if err != nil {
226			t.Fatal(err)
227		}
228		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
229			t.Fatal(err)
230		}
231		if err := m.Close(); err != nil {
232			t.Fatal(err)
233		}
234	
235		// 合法：L/1 与 L/2 都在列表中。
236		m2, err := Open(path)
237		if err != nil {
238			t.Fatalf("open: %v", err)
239		}
240		recs, _ := m2.Corrections()
241		if len(recs) != 1 {
242			t.Fatalf("records = %+v", recs)
243		}
244		lms := recs[0].Landmarks
245		if len(lms) != 2 || lms[0].ID != "L" || lms[0].Occurrence != 1 ||
246			lms[1].ID != "L" || lms[1].Occurrence != 2 {
247			t.Fatalf("landmark changes = %+v", lms)
248		}
249		m2.Close()
250	
251		cases := []struct {
252			name string
253			fn   func(fd *fileData)
254		}{
255			{"drop invalidated old occurrence", func(fd *fileData) {
256				// 只留 L/2：旧出现虽已失效，范围内（含失效端点）仍有它的观测。
257				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[1:]
258			}},
259			{"drop new occurrence", func(fd *fileData) {
260				// 只留 L/1：漏掉新出现的首次观测。
261				fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[:1]
262			}},
263			{"rename old to new", func(fd *fileData) {
264				// L/1 改指 L/2：与原有 L/2 重复，真正的 L/1 缺失。
265				fd.Corrections[0].Landmarks[0].Occurrence = 2
266			}},
267			{"same position does not merge occurrences", func(fd *fileData) {
268				// 把 L/2 的编号改成 1：两次出现即使位置相同也分别对应。
269				fd.Corrections[0].Landmarks[1].Occurrence = 1
270			}},
271		}
272		for _, tc := range cases {
273			t.Run(tc.name, func(t *testing.T) {
274				p := filepath.Join(t.TempDir(), "m.pose")
275				buildOccurrenceMap(t, p)
276				m3, err := Open(p)
277				if err != nil {
278					t.Fatal(err)
279				}
280				if _, err := m3.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
281					t.Fatal(err)
282				}
283				m3.Close()
284				tamperFile(t, p, tc.fn)
285				assertOpenCorrupt(t, p)
286			})
287		}
288	}
289	
290	// 旧校正条目没有出现编号（occurrence 缺省为 0）时继续按第 1 次出现解释：
291	// 范围内确实观测了该路标第 1 次出现则合法；与显式 L/1 同时出现则视为重复。
292	func TestOpenCorrectionMissingOccurrenceNumberLegacy(t *testing.T) {
293		path := filepath.Join(t.TempDir(), "m.pose")
294		buildCorrectionLandmarksMap(t, path)
295	
296		// L/1 的编号抹成 0：按第 1 次出现解释，与 M/1 一起仍恰好覆盖范围。
297		tamperFile(t, path, func(fd *fileData) {
298			fd.Corrections[0].Landmarks[0].Occurrence = 0
299		})
300		m, err := Open(path)
301		if err != nil {
302			t.Fatalf("occurrence 0 should mean occurrence 1: %v", err)
303		}
304		recs, _ := m.Corrections()
305		if got := recs[0].Landmarks[0].Occurrence; got != 1 {
306			t.Fatalf("loaded occurrence = %d, want 1", got)
307		}
308		m.Close()
309	
310		// 再补一条显式 L/1：0 与 1 指向同一出现，重复，拒绝。
311		path2 := filepath.Join(t.TempDir(), "m.pose")
312		buildCorrectionLandmarksMap(t, path2)
313		tamperFile(t, path2, func(fd *fileData) {
314			lcs := fd.Corrections[0].Landmarks
315			zeroed := lcs[0]
316			zeroed.Occurrence = 0
317			fd.Corrections[0].Landmarks = append([]landmarkChangeJSON{zeroed}, lcs...)
318		})
319		assertOpenCorrupt(t, path2)
320	}
321	
322	// 旧地图（无逐帧依据）保留既有打开规则：手工构造一条覆盖 null 旧帧的校正
323	// 记录，其路标列表即使与范围内观测不一致也不按新规则核对（不补造观测）。
324	func TestOpenSkipsLandmarkListCheckWhenRangeLacksBasis(t *testing.T) {
325		path := filepath.Join(t.TempDir(), "m.pose")
326		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
327		m, err := Create(path, cfg)
328		if err != nil {
329			t.Fatal(err)
330		}
331		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
332			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
333			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
334		}}); err != nil {
335			t.Fatal(err)
336		}
337		writeLegacyV1File(t, path, m.state)
338		m.Close()
339	
340		// 追加一帧有完整依据的新帧，然后手写一条覆盖 t=100..300（含 null 旧帧）
341		// 的校正记录，故意只给空路标列表。
342		m2, err := Open(path)
343		if err != nil {
344			t.Fatal(err)
345		}
346		if _, err := m2.ImportSegment(Segment{ID: "new", Frames: []Frame{
347			{Time: 300, DX: 0.5, Observations: []Observation{{ID: "K"}}},
348		}}); err != nil {
349			t.Fatal(err)
350		}
351		if err := m2.Close(); err != nil {
352			t.Fatal(err)
353		}
354		tamperFile(t, path, func(fd *fileData) {
355			cr := corrRecJSON{ID: "span", Anchor: 100, EndTime: 300,
356				Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}
357			for j := 1; j < len(fd.Trajectory); j++ {
358				cr.Poses = append(cr.Poses, poseChangeJSON{Before: fd.Trajectory[j], After: fd.Trajectory[j]})
359			}
360			fd.Corrections = append(fd.Corrections, cr)
361		})
362		m3, err := Open(path)
363		if err != nil {
364			t.Fatalf("range lacking per-frame basis keeps legacy open rules: %v", err)
365		}
366		m3.Close()
367	
368		// 但在旧地图上新追加且依据完整的范围（仅 t=300）做的校正仍受校验：
369		// 少记 K/1 必须拒绝。
370		path2 := filepath.Join(t.TempDir(), "m.pose")
371		m4, err := Create(path2, cfg)
372		if err != nil {
373			t.Fatal(err)
374		}
375		if _, err := m4.ImportSegment(Segment{ID: "old", Frames: []Frame{
376			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
377		}}); err != nil {
378			t.Fatal(err)
379		}
380		writeLegacyV1File(t, path2, m4.state)
381		m4.Close()
382		m5, err := Open(path2)
383		if err != nil {
384			t.Fatal(err)
385		}
386		if _, err := m5.ImportSegment(Segment{ID: "new", Frames: []Frame{
387			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
388		}}); err != nil {
389			t.Fatal(err)
390		}
391		// 锚点取新帧 t=200：范围逐帧依据完整，K/1 在范围内被观测；用恒等目标
392		// 避免与固定旧贡献的合并距离冲突。
393		cur, _ := m5.PoseAt(200)
394		if _, err := m5.Correct(Correction{ID: "cnew", Anchor: 200, Target: CorrectionTarget{
395			X: cur.X, Y: cur.Y, Heading: cur.Heading, Variance: cur.Variance,
396		}}); err != nil {
397			t.Fatal(err)
398		}
399		if err := m5.Close(); err != nil {
400			t.Fatal(err)
401		}
402		tamperFile(t, path2, func(fd *fileData) {
403			fd.Corrections[0].Landmarks = nil
404		})
405		if m6, err := Open(path2); !errors.Is(err, ErrCorrupt) {
406			t.Fatalf("fully-based appended range: err = %v, want ErrCorrupt, map=%v", err, m6)
407		}
408	}
409	
410	// 拒绝打开后原文件字节保持不变（在含校正与失效的复杂文件上再确认一次）。
411	func TestOpenBadCorrectionLandmarkListLeavesFileUntouched(t *testing.T) {
412		path := filepath.Join(t.TempDir(), "m.pose")
413		buildOccurrenceMap(t, path)
414		m, err := Open(path)
415		if err != nil {
416			t.Fatal(err)
417		}
418		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
419			t.Fatal(err)
420		}
421		if err := m.Close(); err != nil {
422			t.Fatal(err)
423		}
424		tamperFile(t, path, func(fd *fileData) {
425			fd.Corrections[0].Landmarks = fd.Corrections[0].Landmarks[:1] // 丢掉 L/2
426		})
427		saved, err := os.ReadFile(path)
428		if err != nil {
429			t.Fatal(err)
430		}
431		if m2, err := Open(path); !errors.Is(err, ErrCorrupt) {
432			t.Fatalf("err = %v, want ErrCorrupt, map=%v", err, m2)
433		}
434		got, err := os.ReadFile(path)
435		if err != nil {
