	// 两次同帧观测（初始位姿 (1,2)、朝向 0）：先在 (1,2) 建路标 Q，
	// 再在 (1,2.5) 合并 → (1,2.25) count2。
	_, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
