	if len(lms) != 1 || lms[0].Count != 2 {
		t.Fatalf("landmarks = %v", lms)
	}
	approxEq(t, "q y", lms[0].Y, 2.25)

	// 同帧第二次观测距当前聚合位置超距也要拒绝整段，且不留第一次观测。
	m2 := newMap(t, baseConfig())
	_, err = m2.ImportSegment(Segment{ID: "s", Frames: []Frame{
